import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { toast } from 'react-toastify';
import CurriculumBuilder from '../components/CurriculumBuilder'; 

const categories = ['Programming', 'Design', 'Business', 'Marketing', 'Photography', 'Music', 'Data Science', 'AI & ML'];

export default function InstructorPage() {
  const [courses, setCourses] = useState([]);
  const [view, setView] = useState('list');
  const [editCourse, setEditCourse] = useState(null);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ 
    title: '', 
    description: '', 
    shortDescription: '', 
    category: 'Programming', 
    level: 'beginner', 
    price: 0, 
    language: 'English', 
    whatYouLearn: [''], 
    requirements: [''], 
    tags: '' 
  });

  const [modules, setModules] = useState([]);

  useEffect(() => {
    axios.get('/api/courses/instructor/my-courses')
      .then(r => setCourses(r.data || []))
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const handleSave = async () => {
    try {
      // 1. Clean modules (remove UI-only flags like isUploading from the content items)
      const cleanedModules = modules.map(m => ({
        ...m,
        content: m.content.map(item => {
          const { isUploading, ...rest } = item; 
          return rest;
        })
      }));

      // 2. Prepare the full payload[cite: 1]
      const payload = { 
        ...form, 
        modules: cleanedModules, 
        tags: typeof form.tags === 'string' 
          ? form.tags.split(',').map(t => t.trim()).filter(Boolean) 
          : form.tags, 
        whatYouLearn: form.whatYouLearn.filter(Boolean), 
        requirements: form.requirements.filter(Boolean) 
      };

      // 3. Send to Backend[cite: 1]
      if (editCourse) {
        const { data } = await axios.put(`/api/courses/${editCourse._id}`, payload);
        setCourses(cs => cs.map(c => c._id === data._id ? data : c));
        toast.success('✅ Course updated successfully!');
      } else {
        const { data } = await axios.post('/api/courses', payload);
        setCourses(cs => [data, ...cs]);
        toast.success('🚀 Course created!');
      }

      setView('list'); 
      setEditCourse(null);
    } catch (err) { 
      console.error(err);
      toast.error(err.response?.data?.message || 'Save failed'); 
    }
  };

  const startEdit = (c) => {
    setEditCourse(c);
    setForm({ 
        ...c, 
        tags: (c.tags || []).join(', '), 
        whatYouLearn: c.whatYouLearn?.length ? c.whatYouLearn : [''], 
        requirements: c.requirements?.length ? c.requirements : [''] 
    });
    setModules(c.modules || []); 
    setView('create');
  };

  const addListItem = (field) => setForm(f => ({ ...f, [field]: [...f[field], ''] }));
  const updateListItem = (field, i, val) => setForm(f => ({ ...f, [field]: f[field].map((x, j) => j === i ? val : x) }));
  const removeListItem = (field, i) => setForm(f => ({ ...f, [field]: f[field].filter((_, j) => j !== i) }));

  const togglePublish = async (c) => {
    try {
      const { data } = await axios.put(`/api/courses/${c._id}`, { isPublished: !c.isPublished });
      setCourses(cs => cs.map(course => course._id === data._id ? data : course));
      toast.success(data.isPublished ? '🚀 Course published!' : '⏸ Course unpublished!');
    } catch (err) { toast.error(err.response?.data?.message || 'Toggle failed'); }
  };

  return (
    <div style={{ minHeight: '100vh', paddingTop: 90 }}>
      <div className="page-container" style={{ padding: '40px 24px' }}>

        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 36, flexWrap: 'wrap', gap: 16 }}>
          <div>
            <h1 style={{ fontSize: 32, fontWeight: 900 }}>
              Instructor <span style={{ background: 'linear-gradient(135deg, #7c3aed, #00f5d4)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>Studio</span>
            </h1>
            <p style={{ color: '#6b6490', marginTop: 4 }}>Create and manage your courses</p>
          </div>
          {view === 'list' ? (
            <button className="btn btn-primary" onClick={() => { setEditCourse(null); setForm({ title: '', description: '', shortDescription: '', category: 'Programming', level: 'beginner', price: 0, language: 'English', whatYouLearn: [''], requirements: [''], tags: '' }); setModules([]); setView('create'); }}>
              + Create New Course
            </button>
          ) : (
            <button className="btn btn-ghost" onClick={() => setView('list')}>← Back to Courses</button>
          )}
        </div>

        {view === 'list' ? (
          <>
            {/* Stats */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: 16, marginBottom: 32 }}>
              {[
                { icon: '📚', label: 'Total Courses', value: courses.length },
                { icon: '✅', label: 'Published', value: courses.filter(c => c.isPublished).length },
                { icon: '👥', label: 'Total Students', value: courses.reduce((a, c) => a + (c.totalStudents || 0), 0) },
                { icon: '⭐', label: 'Avg Rating', value: courses.length ? (courses.reduce((a, c) => a + (c.averageRating || 0), 0) / courses.length).toFixed(1) : '—' },
              ].map(s => (
                <div key={s.label} className="glass" style={{ padding: '20px', textAlign: 'center', borderRadius: 14 }}>
                  <div style={{ fontSize: 28, marginBottom: 6 }}>{s.icon}</div>
                  <div style={{ fontSize: 26, fontWeight: 900, color: '#c084fc' }}>{s.value}</div>
                  <div style={{ fontSize: 11, color: '#6b6490', marginTop: 2 }}>{s.label}</div>
                </div>
              ))}
            </div>

            {/* Course List */}
            {loading ? <div className="loader" style={{ margin: '60px auto' }} /> :
              courses.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '80px 0', border: '1px dashed rgba(124,58,237,0.3)', borderRadius: 20 }}>
                  <div style={{ fontSize: 64, marginBottom: 16 }}>🎬</div>
                  <h3 style={{ fontSize: 20, fontWeight: 700, marginBottom: 8 }}>No courses yet</h3>
                  <p style={{ color: '#6b6490' }}>Create your first course to start teaching!</p>
                </div>
              ) : (
                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                  {courses.map(c => (
                    <div key={c._id} className="glass" style={{ padding: '20px 24px', borderRadius: 16, display: 'flex', alignItems: 'center', gap: 20, flexWrap: 'wrap' }}>
                      <div style={{ flex: 1, minWidth: 200 }}>
                        <div style={{ display: 'flex', gap: 8, marginBottom: 8, flexWrap: 'wrap' }}>
                          <span className="badge badge-purple">{c.category}</span>
                          <span className={`badge ${c.isPublished ? 'badge-neon' : 'badge-gold'}`}>{c.isPublished ? '✓ Live' : '⏸ Draft'}</span>
                        </div>
                        <h3 style={{ fontSize: 17, fontWeight: 700, color: '#f0eeff' }}>{c.title}</h3>
                        <div style={{ fontSize: 13, color: '#6b6490', display: 'flex', gap: 16, marginTop: 4 }}>
                          <span>👥 {c.totalStudents || 0}</span>
                          <span>📚 {c.modules?.length || 0} modules</span>
                          <span>{c.price === 0 ? 'Free' : `$${c.price}`}</span>
                        </div>
                      </div>
                      <div style={{ display: 'flex', gap: 10 }}>
                        <button className="btn btn-ghost btn-sm" onClick={() => startEdit(c)}>✏️ Edit</button>
                        <button className={`btn btn-sm ${c.isPublished ? 'btn-ghost' : 'btn-neon'}`} onClick={() => togglePublish(c)}>
                          {c.isPublished ? '⏸ Unpublish' : '🚀 Publish'}
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )
            }
          </>
        ) : (
          /* Create/Edit Form View */
          <div style={{ maxWidth: 800 }}>
            <h2 style={{ fontSize: 24, fontWeight: 800, marginBottom: 28 }}>{editCourse ? '✏️ Edit Course' : '🚀 Create New Course'}</h2>

            <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
              <div className="form-group">
                <label className="form-label">Course Title *</label>
                <input className="input" value={form.title} onChange={e => setForm(f => ({ ...f, title: e.target.value }))} />
              </div>

              <div className="form-group">
                <label className="form-label">Description *</label>
                <textarea className="input" rows={4} value={form.description} onChange={e => setForm(f => ({ ...f, description: e.target.value }))} />
              </div>

              {/* Curriculum Section[cite: 1] */}
              <CurriculumBuilder modules={modules} setModules={setModules} />

              <div style={{ display: 'flex', gap: 12, paddingTop: 32 }}>
                <button className="btn btn-primary btn-lg" onClick={handleSave}>
                    {editCourse ? '✓ Save Changes' : '🚀 Create Course'}
                </button>
                <button className="btn btn-ghost" onClick={() => setView('list')}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
